"""Regenerate docs/CHECKS-CATALOG.md from world/mass_effect_le2/data.py.

Run from an Archipelago checkout that has the world at worlds/mass_effect_le2:
    python <repo>/tools/checks_catalog.py <repo>/docs/CHECKS-CATALOG.md
"""
import os
import sys

sys.path.insert(0, os.getcwd())

from worlds.mass_effect_le2 import data

STATUS = "V-DB"  # every predicate so far comes from the plot databases; set per row once observed in game

lines = [
    "# Checks catalog (generated by tools/checks_catalog.py; edit data.py, not this file)",
    "",
    "Status: V-DB = predicate from the plot database, not yet observed in game. Excluded = filler only.",
    "",
    "| ID | Location | Region | Category | Predicate | Logic needs | DLC | Excluded | Status |",
    "|---|---|---|---|---|---|---|---|---|",
]
for name, loc in data.LOCATIONS.items():
    needs = ", ".join(loc.needs + (("any of " + " / ".join(loc.any_of),) if loc.any_of else ())) or ""
    lines.append(f"| {data.ID_BASE + loc.offset:#x} | {name} | {loc.region.value} | {loc.category} | `{loc.plot}` | "
                 f"{needs} | {loc.dlc or ''} | {'yes' if loc.excluded else ''} | {STATUS} |")
lines += ["", "## Items", "", "| ID | Item | Classification | Delivery |", "|---|---|---|---|"]
for name, item in data.ITEMS.items():
    lines.append(f"| {data.ID_BASE + item.offset:#x} | {name} | {item.classification.name} | {item.grant or 'client count'} |")
open(sys.argv[1], "w", encoding="utf-8").write("\n".join(lines) + "\n")
